UPDATE blog_notification_recipient
SET read_at = COALESCE(read_at, NOW())
WHERE notification_id = #{notificationId}
  AND user_id = #{userId}
  AND EXISTS (SELECT 1 FROM blog_notification n
              WHERE n.id = #{notificationId} AND n.status = 'PUBLISHED')

